import{_ as n,o as r,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/programmierung/reports-eigene-datenquellen-abfrageassistent1.png",l="/bilder/programmierung/reports-eigene-datenquellen-abfrageassistent-suchkriterium.png",s="/bilder/programmierung/reports-eigene-datenquellen-abfrageassistent-kriterium.png",d="/bilder/programmierung/reports-eigene-datenquellen-name.png",g="/bilder/programmierung/reports-eigene-datenquellen-ergebnis.png",u="/bilder/programmierung/reports-eigene-datenquellen-abfrageeditor.png",o="/bilder/programmierung/reports-eigene-datenquellen-entwurf.png",k=JSON.parse('{"title":"Eigene Datenquellen für Reports definieren","description":"","frontmatter":{"title":"Eigene Datenquellen für Reports definieren","source_pageid":1583,"source_revision":6551},"headers":[],"relativePath":"reporting/programmierung/eigene-datenquellen.md","filePath":"reporting/programmierung/eigene-datenquellen.md"}'),h={name:"reporting/programmierung/eigene-datenquellen.md"};function p(f,e,m,b,c,q){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="eigene-datenquellen-fur-reports-definieren" tabindex="-1">Eigene Datenquellen für Reports definieren <a class="header-anchor" href="#eigene-datenquellen-fur-reports-definieren" aria-label="Permalink to &quot;Eigene Datenquellen für Reports definieren&quot;">​</a></h1><p>Erstellen Sie eine eigene Datenquelle mit dem Abfrageassistenten oder dem Abfrageeditor. Danach steht sie mit ihren Feldern für die Gestaltung des aktuellen Reports zur Verfügung.</p><p>Eigene Datenquellen werden unter <strong>Daten</strong> für den aktuellen Report definiert. Die SQL-Abfrage kann Felder aus einer Tabelle auswählen, mehrere Tabellen verknüpfen und Datensätze gruppieren oder sortieren.</p><p>Öffnen Sie den Reiter <strong>Daten</strong>. Enthält der Report noch keine eigene Datenquelle, ist die Seite zunächst leer. Wählen Sie <strong>Daten → Neu</strong> und anschließend den Abfrageassistenten oder den Abfrageeditor.</p><h2 id="eine-datenquelle-mit-dem-abfrageassistenten-erstellen" tabindex="-1">Eine Datenquelle mit dem Abfrageassistenten erstellen <a class="header-anchor" href="#eine-datenquelle-mit-dem-abfrageassistenten-erstellen" aria-label="Permalink to &quot;Eine Datenquelle mit dem Abfrageassistenten erstellen&quot;">​</a></h2><p><a href="/bilder/programmierung/reports-eigene-datenquellen-abfrageassistent1.png"><img src="'+a+'" alt="Mit dem Abfrageassistenten lassen sich SQL-Befehle erzeugen." loading="lazy"></a></p><p><em>Mit dem Abfrageassistenten lassen sich SQL-Befehle erzeugen.</em></p><p>Der Abfrageassistent ist ein visuelles Hilfsmittel, um SQL-Befehle automatisch zu generieren. Diese Befehle können anschließend noch angepasst werden.</p><h3 id="_1-datenquellen-auswahlen" tabindex="-1">1. Datenquellen auswählen <a class="header-anchor" href="#_1-datenquellen-auswahlen" aria-label="Permalink to &quot;1. Datenquellen auswählen&quot;">​</a></h3><p>Wählen Sie zuerst die Tabellen aus, deren Daten Sie benötigen. Für Schülernamen verwenden Sie zum Beispiel <strong>Schüler</strong>. Übernehmen Sie die Tabelle mit dem Pfeil nach rechts in die Auswahl.</p><p>Sobald Sie eine zweite Tabelle hinzufügen, legen Sie im folgenden Fenster deren Verknüpfung fest. Der SQL-Befehl dafür heißt <strong>JOIN</strong>. Er verbindet Tabellen über passende Schlüsselfelder, etwa eine gemeinsame Schüler-ID. Vorgeschlagen wird ein <strong>InnerJoin</strong>; dabei werden zusammenpassende Datensätze beider Tabellen berücksichtigt.</p><h3 id="_2-felder-fur-die-abfrage-festlegen" tabindex="-1">2. Felder für die Abfrage festlegen <a class="header-anchor" href="#_2-felder-fur-die-abfrage-festlegen" aria-label="Permalink to &quot;2. Felder für die Abfrage festlegen&quot;">​</a></h3><p>Im nächsten Schritt kann angegeben werden, welche Daten in der neuen Datenquelle sichtbar sind. Dies entspricht der <strong>Select-Anweisung</strong> in einem SQL-Befehl. Hierbei werden alle Angaben selektiert, die beispielsweise im DBTextfeld für die neue Datenquelle ausgewählt werden können. Die gewünschten Felder können über das Größer-Zeichen der Auswahl hinzugefügt werden.</p><h3 id="_3-berechnungen-hinzufugen" tabindex="-1">3. Berechnungen hinzufügen <a class="header-anchor" href="#_3-berechnungen-hinzufugen" aria-label="Permalink to &quot;3. Berechnungen hinzufügen&quot;">​</a></h3><p>Mit <strong>Berechnungen hinzufügen</strong> können Sie Werte zusammenfassen, etwa Datensätze zählen oder den größten Wert ermitteln. Solche Berechnungen heißen <strong>Aggregatfunktionen</strong>. Übernehmen Sie das benötigte Feld mit dem Größer-Zeichen in <strong>Gewählte Felder</strong>. Wählen Sie anschließend die Funktion, zum Beispiel <strong>Anzahl</strong> oder <strong>Max</strong>. Der Assistent ergänzt den passenden SELECT-Eintrag. Eine Gruppierung können Sie im nächsten Schritt festlegen.</p><h3 id="_4-gruppierung-hinzufugen" tabindex="-1">4. Gruppierung hinzufügen <a class="header-anchor" href="#_4-gruppierung-hinzufugen" aria-label="Permalink to &quot;4. Gruppierung hinzufügen&quot;">​</a></h3><p>Fügen Sie bei Bedarf eine <strong>GROUP BY-Klausel</strong> hinzu. Sie ist insbesondere bei Aggregatfunktionen hilfreich. Aktivieren Sie „Gruppierungsfelder auswählen“ und verschieben Sie die benötigten Felder über die Pfeile zu den gewählten Feldern.</p><p><a href="/bilder/programmierung/reports-eigene-datenquellen-abfrageassistent-suchkriterium.png"><img src="'+l+'" alt="Die WHERE-Klausel dient dazu, Suchkriterien zu definieren." loading="lazy"></a></p><p><em>Die WHERE-Klausel dient dazu, Suchkriterien zu definieren.</em></p><p><a href="/bilder/programmierung/reports-eigene-datenquellen-abfrageassistent-kriterium.png"><img src="'+s+'" alt="Mit der WHERE-Klausel werden hier nach &quot;volljährigen&quot; Schülern gesucht." loading="lazy"></a></p><p><em>Mit der WHERE-Klausel werden hier nach &quot;volljährigen&quot; Schülern gesucht.</em></p><h3 id="_5-suchkriterium-definieren" tabindex="-1">5. Suchkriterium definieren <a class="header-anchor" href="#_5-suchkriterium-definieren" aria-label="Permalink to &quot;5. Suchkriterium definieren&quot;">​</a></h3><p>Wählen Sie „Suchkriterium definieren“, um eine <strong>WHERE-Klausel</strong> anzulegen. Klicken Sie im zunächst leeren Fenster mit der rechten Maustaste und erstellen Sie ein Kriterium. Das abgebildete Beispiel beschränkt die Datenquelle auf volljährige Schülerinnen und Schüler. Über die rechte Maustaste können Sie weitere Kriterien ergänzen, miteinander verknüpfen und durch Klammern gruppieren.</p><h3 id="_6-sortieren-der-datensatze" tabindex="-1">6. Sortieren der Datensätze <a class="header-anchor" href="#_6-sortieren-der-datensatze" aria-label="Permalink to &quot;6. Sortieren der Datensätze&quot;">​</a></h3><p>Wählen Sie „Sortiert nach Feldinhalt“. Legen Sie ein oder mehrere Sortierfelder und deren Reihenfolge fest. Der Assistent ergänzt dafür die <strong>ORDER BY-Klausel</strong>.</p><p><a href="/bilder/programmierung/reports-eigene-datenquellen-name.png"><img src="'+d+'" alt="Name der Datenquelle" loading="lazy"></a></p><p><em>Name der Datenquelle</em></p><h3 id="_7-fertigstellen" tabindex="-1">7. Fertigstellen <a class="header-anchor" href="#_7-fertigstellen" aria-label="Permalink to &quot;7. Fertigstellen&quot;">​</a></h3><p>Im letzten Schritt kann der eigenen Datenquelle noch ein passender Name gegeben werden. Durch Auswahl von &quot;Fertigstellen&quot; wird das Ergebnis sichtbar.</p><p><a href="/bilder/programmierung/reports-eigene-datenquellen-ergebnis.png"><img src="'+g+'" alt="Über den Editor kann die gerade erstelle SQL-Abfrage weiter bearbeitet werden." loading="lazy"></a></p><p><em>Über den Editor kann die gerade erstelle SQL-Abfrage weiter bearbeitet werden.</em></p><p>Die Datenquelle steht nun im Entwurfsmodus zur Verfügung. Sie können sie später weiter anpassen.</p><p>Klicken Sie auf eines der Symbole oberhalb der Datenquelle, um den Editor zu öffnen. Die Reiter zeigen die einzelnen Schritte des Abfrageassistenten.</p><p>Der Reiter <strong>SQL</strong> zeigt die erzeugte Abfrage. Zum Ändern öffnen Sie mit der rechten Maustaste den Bearbeitungsmodus und bestätigen, dass Sie den SQL-Befehl bearbeiten möchten.</p><p>Bestätigen Sie die Änderung mit <strong>OK</strong>. Die Abfrage wird gespeichert, wenn sie syntaktisch korrekt ist.</p><h2 id="eine-datenquelle-mit-dem-abfrageeditor-erstellen" tabindex="-1">Eine Datenquelle mit dem Abfrageeditor erstellen <a class="header-anchor" href="#eine-datenquelle-mit-dem-abfrageeditor-erstellen" aria-label="Permalink to &quot;Eine Datenquelle mit dem Abfrageeditor erstellen&quot;">​</a></h2><p><a href="/bilder/programmierung/reports-eigene-datenquellen-abfrageeditor.png"><img src="'+u+'" alt="Nutzen Sie den Abfrageeditor, um direkt eigene Abfragen zu erstellen." loading="lazy"></a></p><p><em>Nutzen Sie den Abfrageeditor, um direkt eigene Abfragen zu erstellen.</em></p><p>Alternativ zum Abfrageassistenten kann der SQL-Befehl auch direkt über den Abfrageeditor definiert werden.</p><p>Öffnen Sie <strong>Datei → Neu → Abfrageeditor</strong>.</p><p>Die Reiter Tabellen (1) und Felder (2) sind zwingend notwendig, um eine sinnvolle eigene Datenquelle zu erstellen.</p><p>Über die anderen Reiter können Sie optional weitere SQL-Klauseln ergänzen. Dies entspricht genau den gleichen Schritten, die oben bereits beim Abfrageassistenten erläutert wurden.</p><p>SQL-Kenner können auch direkt über den SQL-Bearbeitungsmodus den Befehl über die Tastatur eingeben.</p><p>Auf diese Art und Weise können beliebig viele eigene Datenquellen für einen Report erstellt werden, die wiederum über eine JOIN-Befehl miteinander verknüpft werden können.</p><h2 id="eigene-datenquelle-auswahlen" tabindex="-1">Eigene Datenquelle auswählen <a class="header-anchor" href="#eigene-datenquelle-auswahlen" aria-label="Permalink to &quot;Eigene Datenquelle auswählen&quot;">​</a></h2><p><a href="/bilder/programmierung/reports-eigene-datenquellen-entwurf.png"><img src="'+o+'" alt="DBTextfeld mit eigener DQ" loading="lazy"></a></p><p><em>DBTextfeld mit eigener DQ</em></p><p>Nachdem eine oder mehrere Datenquellen definiert wurden, stehen diese für die Erstellung des Reports zur Verfügung.</p><p>Somit können beispielsweise DBTextfelder basierend auf der eigenen Datenquelle erstellt werden.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Eigene_Datenquellen_definieren" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 6551.</p>',51)])])}const D=n(h,[["render",p]]);export{k as __pageData,D as default};
